    'attendre': { en: 'to wait / to expect', pron: 'ah-tahn-DRUH', type: 'verb', note: 'attendre QUELQUE CHOSE (no à!): j\u2019attends le bus. Participle attendu.' },
    'envoyer': { en: 'to send', pron: 'ahn-vwah-YAY', type: 'verb', note: 'Y glides: j\u2019envoie, nous envoyons. Participle envoyé.' },
    'apprendre': { en: 'to learn / to teach (someone)', pron: 'ah-PRAHN-druh', type: 'verb', note: 'apprendre à faire = learn to do; apprendre à quelqu\u2019un = teach someone. Participle appris.' },
